contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        uint cBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint cMid = address(c).balance;
        uint ownerMid = address(this).balance;
        uint depositsMid = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint cAfter = address(c).balance;
        uint ownerAfter = address(this).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            ownerMid == ownerBefore + amount &&
            cMid == cBefore - amount &&
            depositsMid == depositsBefore &&
            ownerAfter == ownerMid + cMid &&
            cAfter == 0 &&
            depositsAfter == depositsBefore
        );
    }
}

