// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint cBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        try c.withdraw(amount) {} catch { return; }
        uint cMid = address(c).balance;
        uint ownerMid = address(this).balance;
        uint256 depositsMid;
        try c.depositsCount() returns (uint256 __r) { depositsMid = __r; } catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint cAfter = address(c).balance;
        uint ownerAfter = address(this).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(ownerMid == ownerBefore + amount &&
            cMid == cBefore - amount &&
            depositsMid == depositsBefore &&
            ownerAfter == ownerMid + cMid &&
            cAfter == 0 &&
            depositsAfter == depositsBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
